import json

with open('/root/network.json', 'r') as f:
    data = json.load(f)

# 1. Top-level keys
print("=" * 70)
print("1. TOP-LEVEL KEYS")
print("=" * 70)
for k in sorted(data.keys()):
    v = data[k]
    if isinstance(v, list):
        if len(v) > 0 and isinstance(v[0], list):
            print(f"  {k:20s} -> list of lists, {len(v)} rows x {len(v[0])} cols")
        else:
            print(f"  {k:20s} -> list, length {len(v)}")
    elif isinstance(v, dict):
        print(f"  {k:20s} -> dict with {len(v)} keys: {list(v.keys())[:10]}")
    else:
        print(f"  {k:20s} -> {type(v).__name__}: {v}")

# 2. Dimensions
print("\n" + "=" * 70)
print("2. DIMENSIONS")
print("=" * 70)
for key in ['bus', 'gen', 'branch', 'gencost']:
    if key in data and isinstance(data[key], list):
        rows = len(data[key])
        cols = len(data[key][0]) if rows > 0 and isinstance(data[key][0], list) else 'N/A'
        print(f"  {key:10s}: {rows} rows x {cols} cols")

# 3. Column format descriptions (MATPOWER standard)
print("\n" + "=" * 70)
print("3. COLUMN FORMAT (MATPOWER standard)")
print("=" * 70)

bus_cols = [
    "bus_i", "type", "Pd", "Qd", "Gs", "Bs", "area", "Vm", "Va",
    "baseKV", "zone", "Vmax", "Vmin"
]
gen_cols = [
    "bus", "Pg", "Qg", "Qmax", "Qmin", "Vg", "mBase", "status",
    "Pmax", "Pmin", "Pc1", "Pc2", "Qc1min", "Qc1max", "Qc2min", "Qc2max",
    "ramp_agc", "ramp_10", "ramp_30", "ramp_q", "apf"
]
branch_cols = [
    "fbus", "tbus", "r", "x", "b", "rateA", "rateB", "rateC",
    "ratio", "angle", "status", "angmin", "angmax"
]
gencost_cols = [
    "model", "startup", "shutdown", "ncost", "cost_coeffs..."
]

if 'bus' in data and len(data['bus']) > 0:
    ncols_bus = len(data['bus'][0])
    print(f"\n  BUS ({ncols_bus} columns):")
    for i, c in enumerate(bus_cols[:ncols_bus]):
        print(f"    col {i:2d}: {c}")
    if ncols_bus > len(bus_cols):
        for i in range(len(bus_cols), ncols_bus):
            print(f"    col {i:2d}: (extra column)")

if 'gen' in data and len(data['gen']) > 0:
    ncols_gen = len(data['gen'][0])
    print(f"\n  GEN ({ncols_gen} columns):")
    for i, c in enumerate(gen_cols[:ncols_gen]):
        print(f"    col {i:2d}: {c}")
    if ncols_gen > len(gen_cols):
        for i in range(len(gen_cols), ncols_gen):
            print(f"    col {i:2d}: (extra column)")

if 'branch' in data and len(data['branch']) > 0:
    ncols_br = len(data['branch'][0])
    print(f"\n  BRANCH ({ncols_br} columns):")
    for i, c in enumerate(branch_cols[:ncols_br]):
        print(f"    col {i:2d}: {c}")
    if ncols_br > len(branch_cols):
        for i in range(len(branch_cols), ncols_br):
            print(f"    col {i:2d}: (extra column)")

if 'gencost' in data and len(data['gencost']) > 0:
    ncols_gc = len(data['gencost'][0])
    print(f"\n  GENCOST ({ncols_gc} columns):")
    for i, c in enumerate(gencost_cols[:min(ncols_gc, len(gencost_cols))]):
        print(f"    col {i:2d}: {c}")

# 4. Find branch connecting bus 64 to bus 1501
print("\n" + "=" * 70)
print("4. BRANCH CONNECTING BUS 64 <-> BUS 1501")
print("=" * 70)
found = False
for idx, br in enumerate(data['branch']):
    fbus = br[0]
    tbus = br[1]
    if (fbus == 64 and tbus == 1501) or (fbus == 1501 and tbus == 64):
        found = True
        print(f"  Found at branch index {idx}:")
        print(f"    Raw data: {br}")
        print(f"    ---")
        labels = branch_cols[:len(br)]
        for i, val in enumerate(br):
            label = labels[i] if i < len(labels) else f"col_{i}"
            print(f"    {label:10s} = {val}")
if not found:
    print("  NOT FOUND. Checking if buses 64 and 1501 exist...")
    bus_ids = [b[0] for b in data['bus']]
    print(f"    Bus 64 exists:   {64 in bus_ids}")
    print(f"    Bus 1501 exists: {1501 in bus_ids}")
    # Check nearby buses
    print("    Branches from bus 64:")
    for idx, br in enumerate(data['branch']):
        if br[0] == 64 or br[1] == 64:
            print(f"      idx {idx}: {br[0]} -> {br[1]}")
    print("    Branches from bus 1501:")
    for idx, br in enumerate(data['branch']):
        if br[0] == 1501 or br[1] == 1501:
            print(f"      idx {idx}: {br[0]} -> {br[1]}")

# 5. Reference/slack bus (type == 3)
print("\n" + "=" * 70)
print("5. REFERENCE / SLACK BUS (type = 3)")
print("=" * 70)
for b in data['bus']:
    if b[1] == 3:
        print(f"  Bus ID: {b[0]}")
        labels = bus_cols[:len(b)]
        for i, val in enumerate(b):
            label = labels[i] if i < len(labels) else f"col_{i}"
            print(f"    {label:10s} = {val}")

# 6. Sample rows
print("\n" + "=" * 70)
print("6. SAMPLE ROWS (first 3 of each)")
print("=" * 70)
for key in ['bus', 'gen', 'branch', 'gencost']:
    if key in data and isinstance(data[key], list):
        print(f"\n  --- {key.upper()} ---")
        for i, row in enumerate(data[key][:3]):
            print(f"    row {i}: {row}")

# Bonus: baseMVA and version if present
print("\n" + "=" * 70)
print("7. OTHER METADATA")
print("=" * 70)
for k in data:
    if k not in ['bus', 'gen', 'branch', 'gencost']:
        v = data[k]
        if not isinstance(v, (list, dict)) or (isinstance(v, (list, dict)) and len(str(v)) < 200):
            print(f"  {k}: {v}")
        else:
            print(f"  {k}: ({type(v).__name__}, length {len(v)})")

